using UnityEngine;
using UnityEngine.XR.Interaction.Toolkit;

public partial class WallPlacer_VR : MonoBehaviour
{
    [Header("Prefabs")]
    public GameObject previewPrefab;
    public GameObject realPrefab;

    [Header("XR")]
    public XRRayInteractor rightHandRay;

    [Header("Settings")]
    public float distance = 4f;
    public float gridSize = 0.5f;

    private GameObject previewInstance;
    private bool isPlacing = true;

    void Start()
    {
        StartPlacement();
    }

    void Update()
    {
        if (!isPlacing || previewInstance == null)
            return;

        UpdatePreview();

        // TRIGGER = place
        if (rightHandRay.selectAction.action.WasPressedThisFrame())
        {
            PlaceObject();
        }

        // SECONDARY BUTTON = cancel
        if (rightHandRay.activateAction.action.WasPressedThisFrame())
        {
            CancelPlacement();
        }
    }

    void StartPlacement()
    {
        previewInstance = Instantiate(previewPrefab);
        MakeTransparent(previewInstance);
        isPlacing = true;
    }

    void UpdatePreview()
    {
        if (rightHandRay.TryGetCurrent3DRaycastHit(out RaycastHit hit))
        {
            Vector3 pos = hit.point;

            float height = previewInstance.GetComponentInChildren<Renderer>().bounds.size.y;
            pos.y = height / 2f;

            pos = SnapToGrid(pos, gridSize);

            previewInstance.transform.position = pos;
        }
    }

    void PlaceObject()
    {
        Instantiate(realPrefab, previewInstance.transform.position, Quaternion.identity);
    }

    void CancelPlacement()
    {
        Destroy(previewInstance);
        isPlacing = false;
    }

    void MakeTransparent(GameObject obj)
    {
        foreach (Renderer r in obj.GetComponentsInChildren<Renderer>())
        {
            foreach (Material m in r.materials)
            {
                m.shader = Shader.Find("Legacy Shaders/Transparent/Diffuse");
                Color c = m.color;
                c.a = 0.5f;
                m.color = c;
            }
        }
    }

    Vector3 SnapToGrid(Vector3 pos, float size)
    {
        pos.x = Mathf.Round(pos.x / size) * size;
        pos.z = Mathf.Round(pos.z / size) * size;
        return pos;
    }
}
